operations.query:
mutation UpdateStoppedAgentOrgRunConfig($input: UpdateStoppedAgentOrgRunConfigInput!) {
  updateStoppedAgentOrgRunConfig(input: $input) {
    success
    outcome
    message
    isActive
    editability {
      editable
      reason
      __typename
    }
    fieldErrors {
      path
      message
      __typename
    }
    canonical
    __typename
  }
}
